     "إن استحداث التخصص قد جاء استجابة لحاجة سوق العمل المحلي والعربي للإمداد باختصاصيين مؤهلين بمجال الصناعة التجميلية وتحضير وتركيب المستحضرات التجميلية بالإضافة لخبرتهم ومهارتهم بالإجراءات التجميلية للعناية بالشعر والبشرة وتداخلاتها مع الحالة الصحية والدوائية لمستقبل الخدمة.",
     "يتطلب الالتحاق بالبرنامج الدراسة المنتظمة لمدة أربع سنوات دراسية بواقع 140 ساعة معتمدة موزعة بين المواد النظرية المختصة بالعلوم الأساسية مثل الكيمياء والكيمياء الحيوية وتطبيقاتهما والعلوم الطبية المتعلقة بتشريح جسم الإنسان ووظائف أعضائه وعلم الأمراض وعلوم الأدوية وتداخلاتها بالإضافة لاستخدام المنتجات الطبيعية والزيوت العطرية لأغراض صحية وتجميلية.",
     "كما سيتم تأهيل الطالب وتدريبه على طرق العناية بالبشرة والجلد والشعر والأظافر واستخدام الأجهزة الحديثة لعلاج الأمراض الجلدية ولمقاومة آثار التقدم بالعمر مثل العلاج الضوئي والليزر.",
     "ولتحضير طلبتنا لسوق العمل نقدم لهم تدريبًا وتعليمًا مكثفًا من خلال أساتذة مختصين على مهارات التواصل وتقديم المشورة وإدارة المراكز التجميلية والتسويق ولا نغفل عن أهمية أخلاقيات المهنة وتشريعاتها.",
