   "نموذج امتحان كفاءة",
   "نموذج امتحان مهارات ادارية",
   "اسئلة مقترحة لمادة الريادة والابتكار",
   "تطبيقات الانترنت وشبكات التواصل الاجتماعي",
   "المهارات الحياتية والعملية",
