     "يركز القسم على إعداد الطلبة بالمعرفة والمهارات العملية في مجال تمريض البالغين وفق الممارسات القائمة على الأدلة والبراهين.",
     "وتشمل مجالات التدريس الصحة والانحرافات الصحية لدى البالغين، والمهارات الأساسية، والأمراض الحادة والمزمنة، والتقييم الصحي، والرعاية الحرجة، وتعزيز الصحة، وإدارة الخدمات التمريضية والصحية. كما تشمل اهتمامات أعضاء القسم مجالات مثل أمراض القلب والرئة، السكري، الألم، الأورام، ضبط العدوى، الرعاية التلطيفية وجودة الخدمات الصحية."
