  "visionLabel": "الرؤية والرسالة والأهداف",
  "visionData": {
   "vision": "تخريج كفاءات تمريضية ذات جودة عالية لتلبية احتياجات المجتمع المحلي حسب المعايير العالمية لتعليم التمريض.",
   "mission": "تركز رسالة الكلية على تحقيق المعايير العلمية في تعليم التمريض، وخلق بيئة داعمة للبحث العلمي في الكلية والمؤسسات الصحية، وإعداد ممرضين أكفاء لتلبية احتياجات المرافق الصحية في الأردن، وخاصة في المناطق الجنوبية.",
   "goals": [
    "تخريج ممرضين أكفاء قادرين على تقديم الرعاية الصحية وفق المعايير العالمية.",
    "إكساب الطلبة المهارات التمريضية اللازمة وتطبيق الخطط التمريضية.",
    "رفد القطاع الصحي والتعليمي بممرضين مؤهلين.",
    "دعم التعليم والتدريب التمريضي المستمر والبحث العلمي.",
    "تقديم رعاية صحية شاملة للمرضى في مختلف المراحل العمرية.",
    "المحافظة على علاقات تعاون جيدة مع المجتمع المحلي.",
    "المساهمة في تحسين صحة الفرد والأسرة والمجتمع."
   ],
   "values": []
  },
