     "mission": "توفير مستوى رفيع من التعليم الجامعي في علوم الفيزياء، والارتقاء بالعملية التعليمية وتقديم برامج مواكبة للتطورات العالمية، لإعداد خريجين قادرين على المنافسة والمساهمة في سوق العمل.",
