   "vision": "تتجه الكلية إلى توفير الكفاءات المتميزة والمتخصصة في مجالات تكنولوجيا المعلومات والتقنيات الحديثة، مع تطوير برامج البكالوريوس والدراسات العليا باستمرار لتلبية احتياجات سوق العمل والمجتمع المحلي.",
   "mission": "إعداد كوادر متخصصة في مجالات تكنولوجيا المعلومات من الناحيتين الأكاديمية والعملية، وتقديم تعليم جامعي نوعي يزوّد الخريج بالمعرفة النظرية والخبرة التطبيقية التي يحتاجها سوق العمل.",
   "goals": [
    "إعداد خريجين يمتلكون خبرات نظرية وعملية في البرمجة وتطوير الأنظمة.",
    "إعداد خريجين قادرين على إنشاء شبكات الحاسوب وصيانتها وإدارتها.",
    "إعداد خريجين قادرين على تصميم قواعد البيانات وإدارتها.",
    "إعداد خريجين قادرين على متابعة التطورات السريعة في تكنولوجيا المعلومات والأجهزة الذكية."
   ],
