  "visionLabel": "الرؤية والرسالة والأهداف",
  "visionData": {
   "vision": "تهدف الكلية إلى بناء شخصية علمية متميزة أكاديمياً وبحثياً واجتماعياً، وإنشاء قاعدة أكاديمية وعلمية متميزة في العلوم الزراعية الأساسية والتطبيقية.",
   "mission": "إعداد خريج/مهندس زراعي قادر على: تقديم خدمات زراعية متميزة · تنفيذ بحوث علمية ذات مستوى عالمي · الالتزام بقيم المجتمع المحلي · تقديم خدمات للمحافظة على البيئة · زيادة الإنتاج الزراعي المحلي · دعم سلامة الغذاء.",
   "goals": [
    "وضع وتطوير برامج البكالوريوس والدراسات العليا في العلوم الزراعية بما يتوافق مع المعايير المحلية والعالمية.",
    "رفع مستوى الثقة بخريج الكلية من خلال الإبداع والوسائل التعليمية الحديثة.",
    "إعداد خريجين قادرين على التعامل مع البحث العلمي والتطورات الحديثة في العلوم الزراعية.",
    "تحديد احتياجات المجتمع والاستجابة لها محلياً ودولياً.",
    "بناء التعاون مع المؤسسات العلمية والبحثية محلياً ودولياً.",
    "التحسين المستمر للخطط والبرامج الدراسية لرفع مستوى الخريجين وقدرتهم على المنافسة في سوق العمل.",
    "تحقيق أهداف ومخرجات التعليم وفق المعايير الأكاديمية."
   ],
   "values": []
  },
  "strategyNote": "صفحة الخطة الاستراتيجية موجودة ضمن قائمة الكلية، ويعرضها الموقع كوثيقة مرتبطة وليست نصاً كاملاً داخل الصفحة.",
