     "mission": "يقدم القسم برامج أكاديمية متميزة محلياً وعالمياً، ويسعى إلى التطوير المستمر للقسم ووظائفه لمواكبة التغيرات في بيئة الأعمال الحديثة، مع توفير التسهيلات اللازمة للبحث العلمي والدراسات العليا وإعداد متخصصين في مجالات التنمية والخدمات المجتمعية.",
