  "visionLabel": "الرؤيا والرسالة والأهداف",
  "visionData": {
   "vision": "الجودة التعليمية من خلال برامج أكاديمية وبحثية متنوعة وكفاءات مؤهلة وشراكات متعددة.",
   "mission": "التميز في مجال العلوم الاجتماعية ضمن بيئة تعليمية وبحثية تسهم في تطوير المجتمع.",
   "goals": [
    "أولاً: رفد سوق العمل محلياً وإقليمياً بكفاءات متميزة ومسلحة بالأسس والقواعد التعليمية والمهارات الجيدة بما يخدم توجهات نظام التعليم العالي في مجالات العلوم الاجتماعية المختلفة.",
    "ثانياً: تطوير مجالات البحث العلمي والإعداد المتميز لأعضاء الهيئة التدريسية بما يخدم توجهات الجامعة في تحسين الكفاءة العلمية.",
    "ثالثاً: وضع البرامج والخطط للنهوض بالمستوى التعليمي للطلبة، والنهوض بقدراتهم التنافسية بين خريجي الجامعات الأخرى.",
    "رابعاً: تطوير مستوى الجودة التعليمية والتصنيف الأكاديمي لكافة أقسام الكلية من برامج وخطط والتعليم الإلكتروني."
   ],
   "values": []
  },
