  "visionLabel": "الرؤية الرسالة والاهداف والقيم",
  "visionData": {
   "vision": "نحو كلية متميزة في العلوم التربوية محلياً وإقليمياً والاستثمار الأمثل للموارد البشرية والمادية.",
   "mission": "إعداد الكوادر البشرية التربوية المؤهلة علمياً وعملياً من قادة ومعلمين وأخصائيين لرفد سوق العمل المحلي والإقليمي، والمساهمة في حل المشكلات التربوية من خلال البحوث العلمية، وخدمة المجتمع المحلي بعقد الندوات والمؤتمرات والورش التدريبية.",
   "goals": [
    "تنمية المصادر البشرية العاملة في الكلية مهنياً وفقاً لاحتياجاتهم التدريبية ومتطلبات العمل.",
    "رفد الكلية بأعضاء هيئة تدريس أكفياء.",
    "تحسين البيئة التعليمية التعلمية في الكلية لرفع سوية المواقف التعليمية.",
    "تطوير البرامج الأكاديمية في الكلية بما ينسجم مع المعايير المحلية والإقليمية.",
    "توجيه البحث العلمي ليصب في خدمة العملية التربوية وحل المشكلات.",
    "تفعيل دور الكلية في خدمة المجتمع المحلي فيما يتعلق بالقضايا التربوية والنفسية.",
    "تجويد الخدمات الطلابية المقدمة إليهم."
   ],
   "values": [
    "غرس القيم الإيجابية الخاصة بمهنة التعليم وأخلاقياتها.",
    "الارتقاء بمهنة التعليم والمحافظة على المستوى العلمي الرفيع لخريجي الكلية.",
    "تعزيز قيم العدالة والنزاهة والشفافية والمساءلة في العملية التعليمية.",
    "الانفتاح على التجارب الإنسانية العالمية."
   ]
  },
