  "structureNote": "يعرض موقع الكلية الهيكل التنظيمي كصورة توضح التسلسل الإداري: عميد الكلية ← نائب العميد ومساعدو العميد ← رؤساء الأقسام الثلاثة (المناهج والإدارة التربوية، الإرشاد والتربية الخاصة، علم النفس) ← أعضاء هيئة التدريس والكادر الإداري، مع ارتباط المدرسة النموذجية بالكلية.",
