  "learningOutcomesIntro": "صفحة «مخرجات التعلم» تعرض لكل مقرر دراسي في برامج الكلية رابطَي «النموذج 2» (وصف المقرر) و«النموذج 4» (تحديد مستوى المقرر) حسب الإطار الوطني الأردني للمؤهلات، إلى جانب رقم المقرر واسمه.",
