  "visionLabel": "الرؤية والرسالة والأهداف",
  "visionData": {
   "vision": "الوصول إلى التميز، وإعداد خريج نوعي في مجال التربية الرياضية والتأهيل الرياضي، يجمع بين النظرية والتطبيق.",
   "mission": "تنبثق رسالة كلية علوم الرياضة من رسالة جامعة مؤتة، والتي ترتكز على أسس التميّز التعليمي والأكاديمي المعتمد على التطور العلمي والتكنولوجي في إعداد وتأهيل كوادر بشرية (خريجين) يمتلكون المعارف النظرية والمهارات التطبيقية في مختلف القطاعات التدريسية والتدريبية والصحية، وكذلك التميز في مجال البحث العلمي والأنشطة العلمية والتواصل مع المجتمع المحلي.",
   "goalsLabel": "أهداف الكلية",
   "goals": [
    "إعداد معلمي التربية الرياضية.",
    "إعداد كوادر مؤهلة للعمل في مجال التأهيل الرياضي.",
    "تعزيز الكفايات الفنية للخريجين للعمل في مجال التدريب الرياضي.",
    "تعزيز الكفايات الإدارية للخريجين للعمل في مجالات الإدارة الرياضية.",
    "إجراء البحوث والدراسات العلمية في مختلف مجالات التربية الرياضية.",
    "المساهمة الفاعلة مع الهيئات الحكومية والأهلية العاملة ضمن النطاق الرياضي، من خلال تقديم المشورة العلمية والعملية.",
    "تحقيق أقصى درجات التعاون مع الهيئات والمؤسسات الرياضية العربية والدولية في دراسة القضايا الرياضية.",
    "الاستمرار في تطوير البرامج والمناهج الدراسية، بما يتماشى مع أحدث المستجدات والمعارف العلمية والتكنولوجية في العالم.",
    "المساهمة الفاعلة في تطوير برامج التربية الرياضية في المجتمع.",
    "المساهمة الفاعلة في تقديم خدمات للمجتمع المحلي، والعمل على تنمية وتطوير كوادر المؤسسات الرياضية في المجتمع المحلي في المجالين الإداري والفني."
   ],
   "values": [
    "الانتماء الوطني.",
    "الاعتزاز بالهوية الوطنية.",
    "الجودة والتميز.",
    "القيادة والعمل بروح الفريق.",
    "الحرية الأكاديمية.",
    "العدالة والنزاهة.",
    "الشفافية والمساءلة.",
    "التعلم المستمر.",
    "التعلم الذاتي.",
    "تطوير حرية التربية المهنية."
   ]
  },
