  "aboutText": [
   "بدأت الكلية كقسم للتربية الرياضية في كلية العلوم التربوية في العام الجامعي 1992/1993، ثم افتُتح تخصص معلم مجال التربية الرياضية. ومع توسع الجامعة في برامجها الأكاديمية أُنشئت كلية علوم الرياضة مطلع العام الدراسي 1999/2000.",
   "تحمل الكلية اليوم مسؤولية تخريج شباب أكاديمي مؤهل رياضياً عبر أقسامها الثلاثة (التربية الرياضية، التأهيل الرياضي، التدريب الرياضي)، تحت إشراف نخبة من الأساتذة ذوي الخبرة الطويلة والمدرسين الشباب.",
   "تضم الكلية صالة رئيسية متعددة الأغراض تتسع لنحو 3000 متفرج، وأربع صالات فرعية (جمباز، تمرينات إيقاعية، لياقة بدنية)، ومختبر فسيولوجيا، ومختبر حاسوب، ومسبحاً ربع أولمبي، وملعبي سكواش، وملاعب خارجية متعددة الأغراض. وفي مطلع العام الدراسي 2013/2014 افتُتح ملعب لكرة القدم محاط بمضمار ألعاب قوى.",
   "تقدم الكلية دعماً للمجتمع المحلي عبر تسخير إمكانياتها لخدمة القطاعين الرياضي والشبابي في محافظة الكرك، بفتح ملاعبها ومسبحها وصالاتها لتدريب الفرق المصنّفة، وعقد دورات علمية متخصصة، ومنح شهادات محلية وقارية وعالمية في التدريب والتحكيم بالتعاون مع الاتحادات الرياضية واللجنة الأولمبية الأردنية."
  ],
